            'instructions' => 'Answer all questions. A score of 70% or higher is required to pass. You have up to 3 attempts.',
            'pass_score' => 70,
            'questions' => [
                ['question' => 'Why does monitoring beat calendar spraying?', 'a' => 'Monitoring requires no records', 'b' => 'It treats the problems that actually exist and catches them early', 'c' => 'Calendar spraying is illegal', 'd' => 'Monitoring is faster than spraying', 'correct' => 'B'],
                ['question' => 'What is the cultural defence against rhinoceros beetle?', 'a' => 'Spraying the whole farm weekly', 'b' => 'A clean crown and managed compost away from palms', 'c' => 'Cutting all fronds monthly', 'd' => 'Planting more palms per hectare', 'correct' => 'B'],
                ['question' => 'What is the correct order of control?', 'a' => 'Chemical, biological, cultural', 'b' => 'Cultural, biological, chemical last and at the labelled rate', 'c' => 'Biological, chemical, cultural', 'd' => 'Whatever is cheapest first', 'correct' => 'B'],
                ['question' => 'Why record the pre-harvest interval?', 'a' => 'It is only for the spray operator\'s diary', 'b' => 'It proves residues were kept out of the nuts', 'c' => 'It extends the product\'s shelf life', 'd' => 'It reduces the product cost', 'correct' => 'B'],
                ['question' => 'What is a pest threshold?', 'a' => 'The maximum price of a pesticide', 'b' => 'The level at which control is justified', 'c' => 'The number of palms on the farm', 'd' => 'The legal limit of any chemical', 'correct' => 'B'],
