                ['question' => 'What is the correct governance chain?', 'a' => 'Management elects the board, board elects members', 'b' => 'Members elect the board, board hires and oversees management', 'c' => 'Board owns the cooperative and hires members', 'd' => 'The auditor runs the operations', 'correct' => 'B'],
                ['question' => 'Why must the member register be reconciled annually?', 'a' => 'To increase the membership fee', 'b' => 'To keep votes, shares, and dividends legitimate', 'c' => 'Because the law requires a photo each year', 'd' => 'To remove inactive members automatically', 'correct' => 'B'],
                ['question' => 'What makes a finance report genuinely transparent?', 'a' => 'A report only the treasurer can read', 'b' => 'A readable summary presented to the general assembly', 'c' => 'A report published after the annual audit only', 'd' => 'A report kept confidential from members', 'correct' => 'B'],
                ['question' => 'How should recurring disputes over the same issue be handled?', 'a' => 'By disciplining the members who raise them', 'b' => 'By fixing the unclear rule or broken process behind them', 'c' => 'By ignoring them until the next audit', 'd' => 'By moving the meeting location', 'correct' => 'B'],
